def how_many_times(string: str, substring: str) -> int:
    """ Find how many times a given substring can be found in the original string. Count overlapping cases. """
    if not substring or len(string) < len(substring):  # edge case: if substring is empty or string is shorter than substring
        return 0
    count = 0
    i = 0
    while i < len(string):
        if string[i:i + len(substring)] == substring:
            count += 1
            i += len(substring)
        else:
            i += 1
    return count

