from typing import List
import numpy as np

def validate_input(numbers: List[float]) -> None:
    """Validate the input list"""
    if len(numbers) < 2:
        raise ValueError("Input list must have at least two elements")
    if len(set(numbers)) == 1:
        raise ValueError("All elements in the list must be different")
    if not all(isinstance(x, (int, float)) for x in numbers):
        raise ValueError("Input list must contain only numbers")
    if np.isnan(numbers).any() or np.isinf(numbers).any():
        raise ValueError("Input list must not contain NaN or infinity")

def rescale_to_unit(numbers: List[float]) -> List[float]:
    """Given list of numbers, apply a linear transform to that list,
    such that the smallest number will become 0 and the largest will become 1"""
    validate_input(numbers)
    min_val = min(numbers)
    max_val = max(numbers)
    return [(x - min_val) / (max_val - min_val) for x in numbers]

